const STORIES = [{"id":"lab-82-schools","report_year":"2024","pdf_pages":"302","ministry":"Ministry of Education","place":"82 schools","headline":"Laboratory equipment for 82 schools not delivered","summary":"In June 2024 the Ministry signed four contracts, worth K8,654,504.49 in total, to supply laboratory equipment and reagents to 82 schools within 12 to 16 weeks of the advance payment.","paid":"Advance payments of K2,169,546.90 were made in August and September 2024.","outcome":"A records review and physical check of selected schools in May 2025 found the equipment and reagents 'had not been delivered to all the 82 schools'.","as_at":"May 2025","cite":"Auditor General, 2024 report, PDF page 302","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/lab-82-schools.html"},{"id":"gas-cylinders","report_year":"2025","pdf_pages":"163-164","ministry":"Ministry of Education","place":"Selected schools","headline":"Schools' laboratory gas paid for in full, items missing","summary":"On 13 June 2024 the Ministry contracted Mecs Services Limited to supply laboratory gas cylinders, burners and fittings to schools for K918,511.","paid":"The supplier received a K229,628 advance in August 2024 and the K688,883 balance on 23 May 2025: the full contract sum.","outcome":"A check of selected schools and their delivery records in April 2026 found 1,032 items worth K268,131 not delivered.","as_at":"April 2026","cite":"Auditor General, 2025 report, PDF pages 163-164","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/gas-cylinders.html"},{"id":"heifers-kawambwa","report_year":"2024","pdf_pages":"130-131","ministry":"Ministry of Home Affairs and Internal Security (Zambia Correctional Service)","place":"Kawambwa","headline":"818 heifers ordered for Kawambwa; 100 arrived","summary":"On 15 November 2024 the Zambia Correctional Service engaged three suppliers to deliver 818 yearling heifers to the Chishinga Livestock Breeding Centre in Kawambwa within 4 to 8 weeks, for K10,879,462.","paid":"Two suppliers were paid advances totalling K1,826,824.","outcome":"As at 31 August 2025 one supplier had delivered 100 of its 273 heifers; the other two had delivered none, five months after the contracts expired. There was no evidence that liquidated damages had been claimed.","as_at":"31 August 2025","cite":"Auditor General, 2024 report, PDF pages 130-131","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/heifers-kawambwa.html"},{"id":"bicycles-116-districts","report_year":"2024","pdf_pages":"148","ministry":"Ministry of Community Development and Social Services","place":"All 116 districts","headline":"10,335 bicycles for cash-transfer districts not delivered","summary":"On 18 March 2024 the Ministry contracted Raton Freight Zambia Limited to deliver 10,335 bicycles to all 116 districts under the Social Cash Transfer programme by early June 2024, for K13,947,083.","paid":"An advance of K3,486,771 was paid on 4 April 2024.","outcome":"As at 31 August 2025 no bicycles had been delivered. The Ministry said it had terminated the contract and asked the Attorney General to recover the money; the funds had not been recovered.","as_at":"31 August 2025","cite":"Auditor General, 2024 report, PDF page 148","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/bicycles-116-districts.html"},{"id":"seed-25-districts","report_year":"2024","pdf_pages":"137-138","ministry":"Ministry of Community Development and Social Services","place":"25 districts","headline":"Seed for 62,317 beneficiaries in 25 districts not delivered","summary":"On 28 November 2024 the Ministry contracted Trans Seed Zambia Limited to supply rice, bean and sunflower seed to all 116 districts for the rainfed cropping component of the 2024/25 season, for K31,564,860.","paid":"The supplier had been paid K9,785,106.","outcome":"As at 31 August 2025 the seed had not been delivered. Visits to selected districts found seed costing K12,183,482, meant for 62,317 beneficiaries in 25 districts, not delivered.","as_at":"31 August 2025","cite":"Auditor General, 2024 report, PDF pages 137-138","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/seed-25-districts.html"},{"id":"kanona-ece-serenje","report_year":"2025","pdf_pages":"154","ministry":"Ministry of Education","place":"Kanona, Serenje District","headline":"Serenje early-childhood centre left unfinished","summary":"On 18 April 2023 the Ministry signed a contract with Pozzolana Engineers and Builders Limited for 20 early childhood education hubs, including the Kanona Primary hub at K3,864,753, to be finished within 12 months of site handover.","paid":"Payments of K2,268,039 (58.68% of the Kanona contract sum) had been made by 31 December 2025.","outcome":"A site visit in May 2026 found the contractor had abandoned the site in 2024; the buildings were roofed but plumbing and electrical work were unfinished. The contract had been extended four times, the last in April 2026.","as_at":"May 2026","cite":"Auditor General, 2025 report, PDF page 154","share":"https://chanza-bj.github.io/AG_Report_Analysis/stories/kanona-ece-serenje.html"}];

